"""업무 후보를 규칙 · 고전 ML · LLM 중 어디에 맞는지 판정 — python decide.py
업무마다 질문 다섯 개에 답을 적으면 방식과 이유, 검증 방법을 표로 출력합니다. 외부 패키지 없음.
"""
from dataclasses import dataclass


@dataclass
class Task:
    name: str
    rule_writable: bool      # 판단 기준을 규칙(SQL·if)으로 빠짐없이 쓸 수 있나
    labeled_rows: int        # 정답(라벨)이 붙은 과거 데이터 건수
    free_text_input: bool    # 입력이 자유 문장(메일·문의·문서)인가
    daily_volume: int        # 하루 처리 건수
    exact_answer: bool       # 정답이 하나로 정해지는 일인가 (금액·건수 검증 등)


def decide(t: Task) -> tuple[str, str, str]:
    """(방식, 이유, 검증 방법)"""
    if t.rule_writable or t.exact_answer:
        return ("규칙·SQL", "기준을 규칙으로 쓸 수 있고 결과가 항상 같아야 함",
                "원천 대비 건수·합계 대사, 규칙별 단위 테스트")
    if not t.free_text_input and t.labeled_rows >= 1_000:
        return ("고전 ML", f"숫자·코드 입력이고 라벨 {t.labeled_rows:,}건이 있음",
                "시간 순으로 나눈 평가셋 정확도, 월별 성능 추적")
    if t.free_text_input and t.labeled_rows >= 5_000 and t.daily_volume >= 50_000:
        return ("고전 ML (LLM과 비교 후)", "대량 처리라 건당 비용·지연이 중요하고 라벨이 충분함",
                "같은 평가셋으로 LLM과 정확도·비용 비교")
    return ("LLM", "자유 문장 입력이고 라벨이 적어 학습보다 지시문으로 시작하는 편이 빠름",
            "허용 목록 검증 + 담당자 검수, 고친 결과를 라벨로 축적")


TASKS = [
    Task("일별 적재 건수·합계 검증", True, 0, False, 300, True),
    Task("영업점별 다음 달 신규 계좌 수 예측", False, 36 * 120, False, 1, False),
    Task("운영 메일함 문의 유형 분류·배정", False, 0, True, 150, False),
    Task("콜센터 상담 메모 유형 분류", False, 80_000, True, 60_000, False),
]

if __name__ == "__main__":
    print(f"{'업무':24s} | {'방식':22s} | 이유 | 검증 방법")
    for t in TASKS:
        how, why, check = decide(t)
        print(f"{t.name:24s} | {how:22s} | {why} | {check}")

package study.s01;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.TreeMap;

/**
 * TF-IDF(글자 2~3개 묶음) + 다항 로지스틱 회귀를 직접 구현한 작은 분류기.
 * scikit-learn 의 TfidfVectorizer(analyzer="char_wb", ngram_range=(2, 3)) + LogisticRegression 과 같은 생각입니다.
 * 학습 결과(어휘 · IDF · 가중치)는 이 record 하나이고, JSON 파일 하나로 저장됩니다.
 */
public record TicketModel(List<String> labels, Map<String, Integer> vocab, double[] idf,
                          double[][] weights, double[] bias) {

    /** 정답이 달린 티켓 한 줄 */
    public record Ticket(String text, String label) {}

    /** 학습용 · 평가용 묶음 */
    public record Split(List<Ticket> train, List<Ticket> test) {}

    private static final ObjectMapper JSON = new ObjectMapper();

    // ---------- 데이터 ----------
    public static List<Ticket> loadTickets(Path csv) throws IOException {
        List<String> lines = Files.readAllLines(csv, StandardCharsets.UTF_8);
        List<Ticket> rows = new ArrayList<>();
        for (String line : lines.subList(1, lines.size())) {          // 첫 줄은 헤더(text,label)
            if (line.isBlank()) continue;
            int comma = line.lastIndexOf(',');                         // 라벨에는 쉼표가 없으므로 마지막 쉼표로 나눕니다
            rows.add(new Ticket(line.substring(0, comma), line.substring(comma + 1).strip()));
        }
        return rows;
    }

    /** 유형별로 같은 비율을 평가용으로 떼어 둡니다(stratify). seed 가 같으면 늘 같은 분할입니다. */
    public static Split split(List<Ticket> rows, double testRatio, long seed) {
        Map<String, List<Ticket>> byLabel = new TreeMap<>();
        for (Ticket t : rows) byLabel.computeIfAbsent(t.label(), k -> new ArrayList<>()).add(t);
        Random rnd = new Random(seed);
        List<Ticket> train = new ArrayList<>();
        List<Ticket> test = new ArrayList<>();
        for (List<Ticket> group : byLabel.values()) {
            List<Ticket> g = new ArrayList<>(group);
            Collections.shuffle(g, rnd);
            int nTest = (int) Math.round(g.size() * testRatio);
            test.addAll(g.subList(0, nTest));
            train.addAll(g.subList(nTest, g.size()));
        }
        return new Split(train, test);
    }

    // ---------- 문장 → 숫자 ----------
    /** 한국어는 띄어쓰기가 불규칙하므로 단어 대신 글자 2~3개 묶음을 씁니다. 단어 앞뒤 공백으로 경계를 표시합니다(char_wb). */
    static List<String> grams(String text) {
        List<String> out = new ArrayList<>();
        for (String w : text.toLowerCase(Locale.ROOT).split("\\s+")) {
            if (w.isEmpty()) continue;
            String p = " " + w + " ";
            for (int n = 2; n <= 3; n++) {
                for (int i = 0; i + n <= p.length(); i++) out.add(p.substring(i, i + n));
            }
        }
        return out;
    }

    /** TF-IDF 벡터(길이 1로 정규화). 학습 때 못 본 조각은 버립니다. */
    double[] vectorize(String text) {
        double[] v = new double[vocab.size()];
        for (String g : grams(text)) {
            Integer j = vocab.get(g);
            if (j != null) v[j] += 1.0;
        }
        double norm = 0;
        for (int j = 0; j < v.length; j++) {
            v[j] *= idf[j];
            norm += v[j] * v[j];
        }
        norm = Math.sqrt(norm);
        if (norm > 0) for (int j = 0; j < v.length; j++) v[j] /= norm;
        return v;
    }

    // ---------- 학습 ----------
    /** 학습(training): 정답과 예측의 차이(교차 엔트로피)가 줄도록 가중치를 경사하강법으로 조금씩 고칩니다. */
    public static TicketModel fit(List<Ticket> train, int epochs, double lr, double l2) {
        // 1) 어휘와 IDF — 여러 문서에 흔한 조각일수록 가중치를 낮춥니다
        Map<String, Integer> vocab = new LinkedHashMap<>();
        Map<String, Integer> df = new HashMap<>();
        for (Ticket t : train) {
            for (String g : new HashSet<>(grams(t.text()))) {
                vocab.putIfAbsent(g, vocab.size());
                df.merge(g, 1, Integer::sum);
            }
        }
        int n = train.size();
        double[] idf = new double[vocab.size()];
        vocab.forEach((g, j) -> idf[j] = Math.log((1.0 + n) / (1.0 + df.get(g))) + 1.0);   // scikit-learn 기본식
        List<String> labels = train.stream().map(Ticket::label).distinct().sorted().toList();
        int k = labels.size();

        TicketModel m = new TicketModel(labels, vocab, idf, new double[k][vocab.size()], new double[k]);
        double[][] x = train.stream().map(t -> m.vectorize(t.text())).toArray(double[][]::new);
        int[] y = train.stream().mapToInt(t -> labels.indexOf(t.label())).toArray();

        // 2) 경사하강법: 기울기 = (예측 확률 - 정답) × 입력
        for (int epoch = 0; epoch < epochs; epoch++) {
            double[][] gw = new double[k][vocab.size()];
            double[] gb = new double[k];
            for (int i = 0; i < n; i++) {
                double[] p = m.softmax(x[i]);
                for (int c = 0; c < k; c++) {
                    double err = p[c] - (y[i] == c ? 1.0 : 0.0);
                    gb[c] += err / n;
                    for (int j = 0; j < x[i].length; j++) {
                        if (x[i][j] != 0) gw[c][j] += err * x[i][j] / n;
                    }
                }
            }
            for (int c = 0; c < k; c++) {
                m.bias[c] -= lr * gb[c];
                for (int j = 0; j < vocab.size(); j++) {
                    m.weights[c][j] -= lr * (gw[c][j] + l2 * m.weights[c][j]);   // l2: 가중치가 너무 커지지 않게
                }
            }
        }
        return m;
    }

    // ---------- 추론 ----------
    double[] softmax(double[] x) {
        double[] z = new double[labels.size()];
        double max = Double.NEGATIVE_INFINITY;
        for (int c = 0; c < z.length; c++) {
            double s = bias[c];
            for (int j = 0; j < x.length; j++) if (x[j] != 0) s += weights[c][j] * x[j];
            z[c] = s;
            max = Math.max(max, s);
        }
        double sum = 0;
        for (int c = 0; c < z.length; c++) {
            z[c] = Math.exp(z[c] - max);
            sum += z[c];
        }
        for (int c = 0; c < z.length; c++) z[c] /= sum;
        return z;
    }

    /** 추론(inference): 새 문장에 대해 곱하고 더하는 계산만 합니다. */
    public double[] predictProba(String text) {
        return softmax(vectorize(text));
    }

    public String predict(String text) {
        double[] p = predictProba(text);
        int best = 0;
        for (int c = 1; c < p.length; c++) if (p[c] > p[best]) best = c;
        return labels.get(best);
    }

    // ---------- 저장 · 불러오기 ----------
    public void save(Path file) throws IOException {
        JSON.writeValue(file.toFile(), this);
    }

    public static TicketModel read(Path file) throws IOException {
        return JSON.readValue(file.toFile(), TicketModel.class);
    }
}

package study.s01;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * (a) 고전 ML: 정답 달린 티켓으로 학습하고, 새 티켓을 예측합니다.
 * ./mvnw -q compile exec:java -Dexec.mainClass=study.s01.TrainPredict
 */
public class TrainPredict {
    static final Path DATA = Path.of(System.getProperty("tickets", "../tickets.csv"));   // Python 트랙과 같은 파일
    static final Path MODEL_FILE = Path.of("ticket_model.json");
    static final long SEED = Long.getLong("seed", 42);   // -Dseed=7 처럼 바꿔 분할을 달리해 보세요

    public static void main(String[] args) throws Exception {
        List<TicketModel.Ticket> rows = TicketModel.loadTickets(DATA);

        // 1) 학습용과 평가용을 나눕니다. 평가용은 학습에 절대 쓰지 않습니다.
        TicketModel.Split split = TicketModel.split(rows, 0.25, SEED);

        // 2)·3) 문장을 숫자로 바꾸고, 가중치를 학습합니다.
        long t0 = System.nanoTime();
        TicketModel model = TicketModel.fit(split.train(), 2000, 5.0, 0.04);   // 반복 수 · 학습률 · L2 규제
        System.out.printf("학습 %d건 · 어휘 %d개 · %.0fms%n",
                split.train().size(), model.vocab().size(), (System.nanoTime() - t0) / 1e6);

        // 4) 평가: 처음 보는 문장으로 맞힌 비율을 잽니다.
        report(model, split.test());

        // 5) 저장: 학습 결과(가중치)는 파일 하나입니다. 추론 서버는 이 파일만 있으면 됩니다.
        model.save(MODEL_FILE);
        System.out.printf("저장: %s (%,d bytes)%n", MODEL_FILE, Files.size(MODEL_FILE));

        // 6) 추론: 새 문장에 대해 계산만 합니다.
        for (String text : List.of(
                "새벽 적재 작업이 ORA-00942 오류로 실패했습니다",
                "지점별 예금 잔고를 주간 단위로 보는 화면이 필요합니다")) {
            double confidence = Arrays.stream(model.predictProba(text)).max().orElse(0);
            System.out.printf("%-6s (확신도 %.2f)  %s%n", model.predict(text), confidence, text);
        }
    }

    /** classification_report 의 축약판: 유형별 정밀도 · 재현율과 전체 정확도 */
    static void report(TicketModel m, List<TicketModel.Ticket> test) {
        Map<String, int[]> counts = new TreeMap<>();   // 유형 → [맞힘, 그 유형으로 예측한 수, 실제 그 유형인 수]
        int correct = 0;
        for (TicketModel.Ticket t : test) {
            String p = m.predict(t.text());
            counts.computeIfAbsent(p, k -> new int[3])[1]++;
            counts.computeIfAbsent(t.label(), k -> new int[3])[2]++;
            if (p.equals(t.label())) {
                counts.get(p)[0]++;
                correct++;
            }
        }
        System.out.printf("%-8s %6s %6s %4s%n", "유형", "정밀도", "재현율", "건수");
        counts.forEach((label, v) -> System.out.printf("%-8s %6.2f %6.2f %4d%n", label,
                v[1] == 0 ? 0.0 : (double) v[0] / v[1], v[2] == 0 ? 0.0 : (double) v[0] / v[2], v[2]));
        System.out.printf("정확도 %.0f%% (%d/%d)%n", 100.0 * correct / test.size(), correct, test.size());
    }
}

package study.s01;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.TextBlock;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * (b) LLM 제로샷: 학습 없이 유형 설명만 주고 분류합니다.
 * ./mvnw -q compile exec:java -Dexec.mainClass=study.s01.ZeroShot
 */
public class ZeroShot {
    // 대량 분류는 작고 빠른 모델이 맞습니다
    static final String MODEL = System.getenv().getOrDefault("CLAUDE_MODEL", "claude-haiku-5-5");
    static final Map<String, String> LABELS = new LinkedHashMap<>();
    static {
        LABELS.put("배치장애", "야간·정기 배치, ETL, 적재 작업이 실패하거나 지연됨");
        LABELS.put("데이터문의", "숫자·코드·컬럼 값이 이상하거나 의미를 묻는 질문");
        LABELS.put("권한요청", "계정·조회·접속 권한의 생성, 추가, 회수");
        LABELS.put("보고서요청", "새 보고서·대시보드 또는 기존 보고서 변경 요청");
    }
    static final String SYSTEM = "당신은 증권사 정보계 운영팀의 티켓 분류 담당입니다.\n"
            + LABELS.entrySet().stream().map(e -> "- " + e.getKey() + ": " + e.getValue())
                    .collect(Collectors.joining("\n"))
            + "\n티켓 문장을 읽고 위 유형 이름 중 하나만 출력하세요. 다른 말은 쓰지 않습니다.";

    private static AnthropicClient client;   // 처음 쓸 때 만듭니다 (ANTHROPIC_API_KEY 환경변수)

    static AnthropicClient client() {
        if (client == null) client = AnthropicOkHttpClient.fromEnv();
        return client;
    }

    /** 응답 content 에는 thinking 블록이 먼저 올 수 있으므로 text 블록만 모읍니다. */
    static String textOf(Message msg) {
        return msg.content().stream()
                .flatMap(b -> b.text().stream())
                .map(TextBlock::text)
                .collect(Collectors.joining())
                .strip();
    }

    public static String classify(String ticket) {
        MessageCreateParams params = MessageCreateParams.builder()
                .model(MODEL)
                .maxTokens(1024)
                .system(SYSTEM)
                .addUserMessage(ticket)
                .build();
        String answer = textOf(client().messages().create(params));
        // LLM 출력은 반드시 허용 목록으로 검증합니다
        return LABELS.containsKey(answer) ? answer
                : "분류불가(" + answer.substring(0, Math.min(20, answer.length())) + ")";
    }

    public static void main(String[] args) {
        for (String t : List.of(
                "새벽 적재 작업이 ORA-00942 오류로 실패했습니다",
                "지점별 예금 잔고를 주간 단위로 보는 화면이 필요합니다",
                "외부 감사인이 다음 주까지 DW 조회만 할 수 있게 해 주세요")) {
            System.out.printf("%-8s %s%n", classify(t), t);
        }
    }
}

package study.s01;

import java.util.List;
import java.util.function.UnaryOperator;

/**
 * 두 방식을 같은 평가셋으로 비교합니다. TrainPredict 를 먼저 실행해 ticket_model.json 을 만들어 두세요.
 * ./mvnw -q compile exec:java -Dexec.mainClass=study.s01.Compare
 */
public class Compare {
    public static void main(String[] args) throws Exception {
        var rows = TicketModel.loadTickets(TrainPredict.DATA);
        // TrainPredict 와 같은 seed 로 나누므로 같은 평가용 8건이 나옵니다
        List<TicketModel.Ticket> test = TicketModel.split(rows, 0.25, TrainPredict.SEED).test();
        TicketModel ml = TicketModel.read(TrainPredict.MODEL_FILE);

        run("고전 ML", ml::predict, test);
        run("LLM 제로샷", ZeroShot::classify, test);
    }

    static void run(String name, UnaryOperator<String> classifier, List<TicketModel.Ticket> test) {
        long start = System.nanoTime();
        List<String> preds = test.stream().map(t -> classifier.apply(t.text())).toList();
        double sec = (System.nanoTime() - start) / 1e9;
        long hit = 0;
        for (int i = 0; i < test.size(); i++) if (preds.get(i).equals(test.get(i).label())) hit++;
        System.out.printf("%-10s 정확도 %.0f%%  전체 %.2f초  건당 %.0fms%n",
                name, 100.0 * hit / test.size(), sec, sec / test.size() * 1000);
        for (int i = 0; i < test.size(); i++) {
            var t = test.get(i);
            if (!preds.get(i).equals(t.label())) {
                String head = t.text().substring(0, Math.min(30, t.text().length()));
                System.out.printf("   오답: %s… → %s (정답 %s)%n", head, preds.get(i), t.label());
            }
        }
    }
}
